namespace Reaparr.Domain;

public class PlexMovieMediaData : BasePlexMediaData
{
    public required int PlexMovieId { get; set; }

    public PlexMovie? PlexMovie { get; set; }

    public ICollection<PlexMovieDataStream> Streams { get; init; } = [];

    /// <summary>
    /// The filename generated by Reaparr for Sonarr/Radarr-compatible media naming.
    /// </summary>
    [Column(Order = 6)]
    public string? GeneratedFilename { get; set; }

    /// <summary>Whether the original filename still needs metadata-based enrichment.</summary>
    [Column(Order = 14)]
    public required bool NeedsGeneratedName { get; set; }

    /// <summary>When generated metadata was last synchronized.</summary>
    [Column(Order = 15)]
    public DateTime? GeneratedNameSyncedAt { get; set; }

    public override string GetFileName =>
        !string.IsNullOrEmpty(GeneratedFilename) ? GeneratedFilename : OriginalFilename;

    [NotMapped]
    public override PlexMediaType Type => PlexMediaType.Movie;
}
